 const groupRows=active(rows('groupProducts')).filter(g=>{
  const type=typeById.get(String(g.Product_Type_ID))||'',part=partById.get(String(g.PART_ID))||'',sub=subById.get(String(g.SUB_PART_ID))||'';
  return (!typeSel.length||typeSel.includes(String(type)))&&(!partSel.length||partSel.includes(String(part)))&&(!subSel.length||subSel.includes(String(sub)))
 }).map(g=>[String(g.Group_Product_ID||''),String(g.Group_Product_Name||g.Group_Product_ID||'')]).filter(x=>x[0]).sort((a,b)=>a[1].localeCompare(b[1],'th'));
