if(!document.documentElement.dataset.teamTargetExpandReady){document.documentElement.dataset.teamTargetExpandReady='Y';document.addEventListener('click',e=>{const b=e.target.closest('[data-team-target-toggle],[data-team-target-expand-all],[data-team-target-collapse-all]');if(!b||!$('#targetContent'))return;if(b.hasAttribute('data-team-target-expand-all'))teamTargetsCurrent().forEach(t=>{if(allocationsForTeam(t).length)teamTargetExpandedRows.add(String(t.Target_ID||t._row))});else if(b.hasAttribute('data-team-target-collapse-all'))teamTargetExpandedRows.clear();else{const key=b.dataset.teamTargetToggle;teamTargetExpandedRows.has(key)?teamTargetExpandedRows.delete(key):teamTargetExpandedRows.add(key)}drawTargets()})}
