function forecastScopes(){const items=active(rows('items')),out=new Map();for(const i of items){if(!i.Product_Type||!i.PART||!i.SUB_PART)continue;const k='S|'+[i.Product_Type,i.PART,i.SUB_PART].join('|');if(!out.has(k))out.set(k,{key:k,level:'SUB_PART',Product_Type:i.Product_Type,PART:i.PART,SUB_PART:i.SUB_PART,Group_Product_ID:'',Group_Product_Name:'',label:'SUB-PART · '+i.SUB_PART+' — '+i.PART+' / '+i.Product_Type})}for(const gp of active(rows('groupProducts'))){const related=items.filter(i=>String(i.Group_Product_ID||'')===String(gp.Group_Product_ID||''));for(const i of related){const k='G|'+String(gp.Group_Product_ID);if(!out.has(k))out.set(k,{key:k,level:'GROUP_PRODUCT',Product_Type:i.Product_Type,PART:i.PART,SUB_PART:i.SUB_PART,Group_Product_ID:String(gp.Group_Product_ID),Group_Product_Name:gp.Group_Product_Name||'',label:'GROUP PRODUCT · '+(gp.Group_Product_Name||gp.Group_Product_ID)+' — '+i.SUB_PART+' / '+i.PART})}}return [...out.values()].sort((a,b)=>a.label.localeCompare(b.label,'th'))}
function forecastUomFactor(scope,uom){const items=active(rows('items')).filter(i=>scope.level==='GROUP_PRODUCT'?String(i.Group_Product_ID||'')===String(scope.Group_Product_ID):i.Product_Type===scope.Product_Type&&i.PART===scope.PART&&i.SUB_PART===scope.SUB_PART),codes=new Set(items.map(i=>String(i.Item_Code))),f=new Set();if(String(uom).toUpperCase()==='KG')return 1;if(String(uom).toUpperCase()==='MT')return 1000;for(const r of rows('itemUoms'))if(codes.has(String(r.Item_Code))&&String(r.UOM).toUpperCase()===String(uom).toUpperCase()&&String(r.Active||'Y').toUpperCase()!=='N'&&Number(r.KG_Per_UOM)>0)f.add(Number(r.KG_Per_UOM));for(const i of items)if(String(i.Base_UOM).toUpperCase()===String(uom).toUpperCase()&&Number(i.KG_Per_UOM)>0)f.add(Number(i.KG_Per_UOM));return f.size===1?[...f][0]:0}
function forecastUoms(scope){const items=active(rows('items')).filter(i=>scope.level==='GROUP_PRODUCT'?String(i.Group_Product_ID||'')===String(scope.Group_Product_ID):i.Product_Type===scope.Product_Type&&i.PART===scope.PART&&i.SUB_PART===scope.SUB_PART),set=new Set(['KG','MT']);for(const i of items)if(i.Base_UOM)set.add(String(i.Base_UOM));const codes=new Set(items.map(i=>String(i.Item_Code)));for(const r of rows('itemUoms'))if(codes.has(String(r.Item_Code))&&String(r.Active||'Y').toUpperCase()!=='N'&&r.UOM)set.add(String(r.UOM));return [...set].filter(u=>forecastUomFactor(scope,u)>0).sort((a,b)=>a.localeCompare(b,'th'))}
