function forecastLevelSelect(value){return '<select id="pfLevel"><option value="">เลือกระดับสินค้า</option>'+forecastScopes().map(x=>'<option value="'+esc(encodeURIComponent(x.key))+'" '+(value===x.key?'selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select>'}
