function bindProductionForecast(){const level=$('#pfLevel');function updateUnits(){const scope=forecastScopes().find(x=>x.key===forecastLevelValue(level?.value)),u=$('#pfUom');if(!u)return;u.innerHTML=(scope?forecastUoms(scope):['KG','MT']).map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('');updateConversion()}function updateConversion(){const scope=forecastScopes().find(x=>x.key===forecastLevelValue(level?.value)),u=$('#pfUom')?.value,f=scope?forecastUomFactor(scope,u):0,q=Number($('#pfQty')?.value||0);$('#pfConversion').textContent=scope&&f?fmt(q,3)+' '+u+' × '+fmt(f,3)+' KG/'+u+' = '+fmt(q*f,3)+' KG = '+fmt(q*f/1000,3)+' MT':'เลือกสินค้าและหน่วยเพื่อดูค่าที่แปลงเป็น KG / MT'}level?.addEventListener('change',updateUnits);$('#pfQty')?.addEventListener('input',updateConversion);$('#pfUom')?.addEventListener('change',updateConversion);$('#pfMonth').onchange=()=>{productionMonth=$('#pfMonth').value;render()};$('#pfImport').onclick=()=>$('#pfUpload').click();$('#pfUpload').onchange=e=>importProductionForecast(e.target.files[0]);$('#pfTemplate').onclick=downloadProductionForecastTemplate;$('#pfExport').onclick=()=>exportRows(rows('dailyProductionForecast').filter(x=>String(x.Data_Status||'LIVE').toUpperCase()==='LIVE'&&normDate(x.Forecast_Date).slice(0,7)===$('#pfMonth').value),'T_DAILY_PRODUCTION_FORECAST');$('#pfCancel')?.addEventListener('click',()=>{selectedForecastId='';render()});$('#pfSave').onclick=saveProductionForecast;$('#app').querySelectorAll('[data-pf-edit]').forEach(b=>b.onclick=()=>{selectedForecastId=b.dataset.pfEdit;render()});$('#app').querySelectorAll('[data-pf-delete]').forEach(b=>b.onclick=()=>deleteProductionForecast(b.dataset.pfDelete));updateConversion()}

