function weeklyPlansView(){const w=weeklyWeekSelection||nextPlanningWeek();return `<section class="weekly-toolbar"><div class="weekly-filter-group" style="grid-template-columns:minmax(180px,260px)"><div class="field"><label>สัปดาห์สำหรับดู/จัดการแผน</label><select id="weeklyWeek">${weekChoices().map(x=>`<option value="${x}" ${x===w?'selected':''}>${x.replace(/^W/,'WEEK ')}</option>`).join('')}</select></div></div><div class="weekly-action-groups"><div class="weekly-plan-actions"><button type="button" class="btn" data-week-fullscreen aria-expanded="false">ขยายตาราง</button></div><div class="weekly-plan-actions"><button class="btn" id="cloneWeek">ดึงแผนสัปดาห์ก่อน</button><button class="btn primary" id="newWeekly">+ บันทึกแผนสัปดาห์</button></div><div class="weekly-file-actions"><button class="btn" id="weeklyImport">Import Excel</button><input type="file" id="weeklyUpload" accept=".xlsx,.xls,.csv" class="hidden"><button class="btn" id="weeklyTemplate">ดาวน์โหลด Template</button><button class="btn" id="weeklyExport">Export Excel</button></div></div></section><div class="card" id="actionContent"><div class="row space"><div><h3>ลูกค้าที่มีฐานการใช้</h3><div class="smallmuted">Sale อ้างอิงจาก Customer Master และปรับได้ต่อรายการในแผนสัปดาห์ · เลือกหลาย Sale ได้จากตัวกรองด้านบน</div></div><span class="badge">Contact / Spot · UOM ตาม Master</span></div></div>`}
function weekChoices(){const set=new Set();for(let i=-10;i<=10;i++){const d=new Date(`${localToday()}T12:00:00`);d.setDate(d.getDate()+i*7);set.add(isoWeek(d.toISOString().slice(0,10)))}rows('weeklyPlans').forEach(x=>x.Week_Key&&set.add(x.Week_Key));return [...set].filter(Boolean).sort((a,b)=>{const x=toWeekRange(a).start,y=toWeekRange(b).start;return x.localeCompare(y)})}
function contactAcceptancePct(planMT,actualMT){const plan=Number(planMT||0);return plan>0?Number(actualMT||0)/plan*100:null}
