async function clonePreviousWeek(){
 try{
  const week=$('#weeklyWeek')?.value||isoWeek(localToday()),range=toWeekRange(week);
  if(!range.start||!range.end)throw Error('กรุณาเลือกสัปดาห์เป้าหมายให้ถูกต้อง');
  const prevDate=new Date(`${range.start}T12:00:00Z`);prevDate.setUTCDate(prevDate.getUTCDate()-7);
  const prev=isoWeek(prevDate.toISOString().slice(0,10));
  const source=rows('weeklyPlans').filter(x=>x.Week_Key===prev&&String(x.Data_Status||'LIVE').toUpperCase()==='LIVE');
  if(!source.length)throw Error(`ไม่พบฐานที่บันทึกไว้ในสัปดาห์ ${prev}`);
  const target=rows('weeklyPlans').filter(x=>x.Week_Key===week&&String(x.Data_Status||'LIVE').toUpperCase()==='LIVE');
  const targetKeys=new Set(target.map(x=>weeklyPlanCopyKey(week,x)));
  const cloned=[],seen=new Set();
  for(const x of source){
   const copy=cloneWeeklyPlanRow(x,week),key=weeklyPlanCopyKey(week,copy,copy.Plan_Date);
   if(targetKeys.has(key)||seen.has(key))continue;
   seen.add(key);cloned.push(copy)
  }
  if(cloned.length){await append(TAB.weeklyPlans,cloned);await loadDb()}
  const targetPlans=rows('weeklyPlans').filter(x=>x.Week_Key===week&&String(x.Data_Status||'LIVE').toUpperCase()==='LIVE');
  if(!targetPlans.length)throw Error('สร้างสำเนาแผนไม่สำเร็จ กรุณาลองใหม่');
  ping(cloned.length?`คัดลอกแผน ${prev} เป็น ${week} แล้ว ${cloned.length} รายการ · แก้ไข/ลบ/เพิ่มได้เลย`:`มีแผน ${week} อยู่แล้ว จึงไม่สร้างรายการซ้ำ · เปิดแผนเดิมให้แก้ไข`);
  openWeeklyEditor(week,'',targetPlans)
 }catch(e){ping(e.message||'ดึงแผนสัปดาห์ก่อนไม่สำเร็จ',true)}
}
