function calendarMonth(list){const grouped=new Map();for(const a of list){const d=actionDateForView(a);if(!d)continue;const key=d.slice(0,7);if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(a)}let months=filterState.periodMode==='month'&&filterState.periods.length?filterState.periods:[...grouped.keys()];if(!months.length)months=[localToday().slice(0,7)];return months.sort().map(month=>{const [y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()+6)%7,days=new Date(y,m,0).getDate(),cells=Array.from({length:offset},()=>'<div class="calendar-cell blank"></div>');for(let d=1;d<=days;d++){const dayKey=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,events=(grouped.get(month)||[]).filter(a=>actionDateForView(a)===dayKey);cells.push(`<div class="calendar-cell"><b>${d}</b>${events.map(a=>`<div class="calendar-entry"><button class="calendar-event" data-edit="${esc(a.Action_ID)}"><small>${esc(dayKey)}</small><br><b>${esc(actionCustomerName(a))}</b><br>${esc(a.Action_Type||'')} · ${esc(a.Status||'')}<br>${esc(a.Next_Action||a.Result||'')}</button><button class="calendar-remove" data-del="${esc(a.Action_ID)}" aria-label="ลบ Action">×</button></div>`).join('')}</div>`)}return `<section class="calendar-month"><h3>${esc(month)}</h3><div class="calendar-grid">${['จ','อ','พ','พฤ','ศ','ส','อา'].map(x=>`<div class="calendar-head">${x}</div>`).join('')}${cells.join('')}</div></section>`}).join('')}
