 $('#masterFilterApply').onclick=()=>{state.q=$('#masterFilterQ').value;state.filters=Object.fromEntries(filterDefs.map(k=>[k,[...(state.draft[k]||[])]]));state.draft={...state.filters};state.draftQ=state.q;state.page=1;drawMaster()};
