  const wb=XLSX.read(await file.arrayBuffer()),tab=TAB[mtab],sheet=wb.Sheets[tab]||wb.Sheets[wb.SheetNames[0]],data=XLSX.utils.sheet_to_json(sheet,{defval:''});
