function teamTargetTable(data){return '<div class="tablewrap"><table class="compact-table"><thead><tr><th>ปี</th><th>เดือน</th><th>Channel / Team</th><th>Product Type</th><th>PART</th><th>SUB-PART</th><th>ระดับเป้า / Group Product</th><th class="num">Team Target (MT)</th><th class="num">แบ่งราย Sale (MT)</th><th class="num">คงเหลือ (MT)</th><th>Coverage</th><th>จัดการ</th></tr></thead><tbody>'+data.map(t=>{const ss=allocationsForTeam(t),v=ss.reduce((n,x)=>n+Number(x.Target_MT||0),0),goal=Number(t.Plan_MT||0),g=groupForTarget(t);return '<tr><td>'+esc(t.Year)+'</td><td>'+String(t.Month).padStart(2,'0')+'</td><td>'+esc(t.Channel)+'</td><td>'+esc(g.Product_Type)+'</td><td>'+esc(g.PART)+'</td><td>'+esc(g.SUB_PART)+'</td><td>'+esc(targetDimensionLabel(t))+'</td><td class="num">'+fmt(goal)+'</td><td class="num">'+fmt(v)+' · '+ss.length+' Sale</td><td class="num">'+fmt(goal-v)+'</td><td>'+fmt(goal?v/goal*100:0,1)+'%</td><td><div class="row nowrap"><button class="btn small" data-team-edit="'+t._row+'">แก้ไข</button><button class="btn small primary" data-team-split="'+t._row+'">แบ่งให้ Sale</button><button class="btn small danger" data-team-delete="'+t._row+'">ลบ</button></div></td></tr>'}).join('')||'<tr><td colspan="12" class="empty">ยังไม่มีเป้าหมายของเดือนนี้</td></tr>'+'</tbody></table></div>'}
function splitTable(data){return '<div class="tablewrap"><table class="compact-table"><thead><tr><th>ปี</th><th>เดือน</th><th>Channel</th><th>Product Type</th><th>PART</th><th>SUB-PART</th><th>ระดับเป้า / Group Product</th><th>Sale</th><th class="num">Target (MT)</th><th>สถานะ</th></tr></thead><tbody>'+data.map(t=>{const g=groupForTarget(t);return '<tr><td>'+esc(t.Year)+'</td><td>'+String(t.Month).padStart(2,'0')+'</td><td>'+esc(t.Channel)+'</td><td>'+esc(g.Product_Type)+'</td><td>'+esc(g.PART)+'</td><td>'+esc(g.SUB_PART)+'</td><td>'+esc(targetDimensionLabel(t))+'</td><td>'+esc(rows('sales').find(s=>s.Sale_ID===t.Sale_ID)?.Sale_Name||t.Sale_ID)+'</td><td class="num">'+fmt(t.Target_MT)+'</td><td>'+esc(t.Status||'DRAFT')+'</td></tr>'}).join('')||'<tr><td colspan="10" class="empty">ยังไม่มีเป้ารายบุคคล</td></tr>'+'</tbody></table></div>'}
function targetCoverage(team){
 if(!team.length)return `<div class="empty">ยังไม่มีเป้าทีมในช่วงเวลานี้</div>`;
 const roots=new Map(),make=(label,level)=>({label,level,children:new Map(),goal:0,divided:0,sales:new Map(),hasTarget:false});
 for(const t of team){const g=groupForTarget(t),type=g.Product_Type||'(ไม่ระบุ Product Type)',part=g.PART||'(ไม่ระบุ PART)',sub=g.SUB_PART||'(ไม่ระบุ SUB-PART)',isGroup=targetLevel(t)==='GROUP_PRODUCT',gp=g.Group_Product_Name||g.Group_Product_ID||'(ไม่ระบุ Group Product)';
  let a=roots.get(type);if(!a){a=make(type,'PRODUCT_TYPE');roots.set(type,a)}
  let b=a.children.get(part);if(!b){b=make(part,'PART');a.children.set(part,b)}
  let c=b.children.get(sub);if(!c){c=make(sub,'SUB_PART');b.children.set(sub,c)}
  let leaf=c;if(isGroup){leaf=c.children.get(gp);if(!leaf){leaf=make(gp,'GROUP_PRODUCT');c.children.set(gp,leaf)}}
  leaf.goal+=Number(t.Plan_MT||0);leaf.hasTarget=true;
  for(const x of allocationsForTeam(t)){const amount=Number(x.Target_MT||0),name=rows('sales').find(s=>s.Sale_ID===x.Sale_ID)?.Sale_Name||x.Sale_ID||'ไม่ระบุ Sale';leaf.divided+=amount;leaf.sales.set(name,(leaf.sales.get(name)||0)+amount)}
 }
 const roll=n=>{for(const child of n.children.values()){roll(child);n.goal+=child.goal;n.divided+=child.divided}};for(const n of roots.values())roll(n);
 const cells=n=>`<span>${fmt(n.goal)} MT</span><span>${fmt(n.divided)} MT</span><span>${fmt(n.goal-n.divided)} MT</span><span><span class="badge ${n.goal&&n.divided>=n.goal?'ok':'warn'}">${fmt(n.goal?n.divided/n.goal*100:0,1)}%</span></span>`;
 const render=(n,depth=0)=>{const kids=[...n.children.values()],row=`<div class="hierarchy-row hierarchy-${n.level.toLowerCase()}" style="--tree-indent:${depth*20}px"><span class="hierarchy-name">${esc(n.label)}</span>${cells(n)}</div>`,sales=n.hasTarget&&n.sales.size?`<details class="hierarchy-sales-detail"><summary>รายละเอียดแบ่งราย Sale (${n.sales.size})</summary><div class="hierarchy-sales">${[...n.sales].map(([name,v])=>`<div class="hierarchy-sale-row"><span>${esc(name)}</span><b>${fmt(v)} MT</b></div>`).join('')}</div></details>`:'';if(!kids.length)return `<div class="hierarchy-leaf">${row}${sales}</div>`;return `<details class="hierarchy-node"><summary>${row}</summary><div class="hierarchy-children">${kids.map(x=>render(x,depth+1)).join('')}</div></details>`};
 return `<div class="target-hierarchy"><div class="hierarchy-controls" style="display:flex;justify-content:flex-end;gap:8px;padding:8px 0"><button type="button" class="btn" data-tree-expand-all>Expand All</button><button type="button" class="btn" data-tree-collapse-all>Collapse All</button></div><div class="hierarchy-row hierarchy-head"><span>PRODUCT_TYPE / PART / SUB_PART / GROUP_PRODUCT</span><span>เป้าทีม</span><span>แบ่งราย Sale</span><span>คงเหลือ</span><span>% Cover</span></div>${[...roots.values()].map(x=>render(x)).join('')}</div>`
}
