/* Click a plain table heading to sort that column; click again to reverse order. */
document.addEventListener('click',function(e){
 const th=e.target.closest('thead th');if(!th||e.target.closest('button, a, input, select'))return;
 const table=th.closest('table'),head=table?.tHead;if(!table||!head)return;
 const hr=head.rows[head.rows.length-1];if(!hr||[...hr.cells].some(c=>c.colSpan>1||c.rowSpan>1))return;
 const idx=[...hr.cells].indexOf(th);if(idx<0)return;
 const body=table.tBodies[0];if(!body)return;
 const dir=table.dataset.sortIndex===String(idx)&&table.dataset.sortDir==='asc'?'desc':'asc';
 table.dataset.sortIndex=String(idx);table.dataset.sortDir=dir;
 const rows=[...body.rows].map((row,n)=>({row,n,value:(row.cells[idx]?.innerText||'').trim()}));
 const numeric=rows.filter(x=>x.value).every(x=>/^[+-]?[\d,.%\s]+(?:MT|KG)?$/i.test(x.value));
 rows.sort((a,b)=>{
  let c;
  if(numeric){const n=x=>Number(x.value.replace(/,/g,'').replace(/%|MT|KG/gi,'').trim())||0;c=n(a)-n(b)}
  else c=a.value.localeCompare(b.value,undefined,{numeric:true,sensitivity:'base'});
  return (dir==='asc'?c:-c)||a.n-b.n;
 });
 rows.forEach(x=>body.appendChild(x.row));crmUpdateTablePagination(table);
 [...hr.cells].forEach(c=>{c.removeAttribute('aria-sort');c.classList.remove('sorted-col')});
 th.setAttribute('aria-sort',dir==='asc'?'ascending':'descending');th.classList.add('sorted-col');
});

function channelUniqueRows(){const seen=new Set();return active(rows('channels')).filter(x=>{const k=String(x.Channel_Code||'').trim().toLocaleLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true})}
function customerLookupRows(key){const conf={Customer_Segment:['customerSegments','Customer_Segment_Code','Customer_Segment_Name'],Route:['routes','Route_Code','Route_Name'],Customer_Status:['customerStatuses','Customer_Status_Code','Customer_Status_Name']}[key];if(!conf)return[];return active(rows(conf[0])).map(x=>[String(x[conf[2]]||x[conf[1]]||''),String(x[conf[2]]||x[conf[1]]||'')]).filter(x=>x[0])}
function masterFieldInput(key,existing={}){
 if(mtab==='customers'&&['Customer_Segment','Route','Customer_Status','Assigned_Sale_ID','Channel'].includes(key)){
  const current=String(existing[key]??'');let values=key==='Assigned_Sale_ID'?active(rows('sales')).map(x=>[x.Sale_ID,(x.Sale_Name||x.Sale_ID)+' · '+x.Sale_ID]):key==='Channel'?channelUniqueRows().map(x=>[x.Channel_Code,x.Channel_Name||x.Channel_Code]):customerLookupRows(key);
  if(current&&!values.some(x=>String(x[0])===current))values.unshift([current,current]);
  const label=key.replace(/_/g,' ');
  return '<select data-master-key="'+esc(key)+'"><option value="">เลือก '+esc(label)+'</option>'+values.map(([v,l])=>'<option value="'+esc(v)+'" '+(String(v)===current?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';
 }
 if(mtab==='channels'&&key==='Channel_Code')return '<input data-master-key="Channel_Code" value="'+esc(existing[key]||'')+'" placeholder="รหัส Channel">';
 return masterFieldInputBase(key,existing);
}

/* Paginate long data tables so the headers remain close to the visible rows. */
let crmTablePageId=0;
function crmUpdateTablePagination(table){
 if(!table||!table.closest('.tablewrap'))return;
 const body=table.tBodies[0];if(!body)return;
 const rows=[...body.rows],wrap=table.closest('.tablewrap');
 if(rows.length<=10){rows.forEach(r=>r.hidden=false);wrap.parentElement?.querySelector('[data-table-pager="'+table.id+'"]')?.remove();return}
 if(!table.id)table.id='crm-data-table-'+(++crmTablePageId);
 const size=table.dataset.pageSize==='all'?rows.length:Math.max(1,Number(table.dataset.pageSize||10)),pages=Math.max(1,Math.ceil(rows.length/size));
 const page=Math.min(Math.max(1,Number(table.dataset.page||1)),pages);table.dataset.page=String(page);
 rows.forEach((r,i)=>r.hidden=i<(page-1)*size||i>=page*size);
 let bar=wrap.parentElement?.querySelector('[data-table-pager="'+table.id+'"]');
 if(!bar){bar=document.createElement('div');bar.className='table-pagination';bar.dataset.tablePager=table.id;bar.innerHTML='<button type="button" class="btn small" data-crm-page="-1">ก่อนหน้า</button><span class="pager-status"></span><label>แสดง <select data-crm-size><option value="10">10</option><option value="25">25</option><option value="50">50</option><option value="all">ทั้งหมด</option></select> แถว</label><button type="button" class="btn small" data-crm-page="1">ถัดไป</button>';wrap.parentElement.insertBefore(bar,wrap)}
 const status=bar.querySelector('.pager-status'),statusText=page+'/'+pages+' · '+((page-1)*size+1)+'–'+Math.min(page*size,rows.length)+' จาก '+rows.length+' รายการ';if(status&&status.textContent!==statusText)status.textContent=statusText;
 const select=bar.querySelector('[data-crm-size]');if(select)select.value=table.dataset.pageSize||'10';
 const buttons=bar.querySelectorAll('[data-crm-page]');if(buttons.length===2){buttons[0].disabled=page<=1;buttons[1].disabled=page>=pages}
}
function crmScanTablePagination(){document.querySelectorAll('.tablewrap table').forEach(crmUpdateTablePagination)}
document.addEventListener('click',function(e){const b=e.target.closest('[data-crm-page]');if(!b)return;const bar=b.closest('[data-table-pager]'),table=bar&&document.getElementById(bar.dataset.tablePager);if(!table)return;table.dataset.page=String(Math.max(1,Number(table.dataset.page||1)+Number(b.dataset.crmPage)));crmUpdateTablePagination(table)});
document.addEventListener('change',function(e){if(!e.target.matches('[data-crm-size]'))return;const bar=e.target.closest('[data-table-pager]'),table=bar&&document.getElementById(bar.dataset.tablePager);if(!table)return;table.dataset.pageSize=e.target.value;table.dataset.page='1';crmUpdateTablePagination(table)});
const crmAppRoot=document.querySelector('#app');if(crmAppRoot&&window.MutationObserver){let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;setTimeout(()=>{queued=false;crmScanTablePagination()},0)}).observe(crmAppRoot,{childList:true,subtree:true});setTimeout(crmScanTablePagination,0)}

